public class ShapeMathTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round2(double x) {
        return Math.round(x * 100.0) / 100.0;
    }

    public static void main(String[] args) {
        check("Rect(2, 3) area", 6.0, new ShapeMath.Rect(2.0, 3.0).area());
        check("Rect(2.5, 4) area", 10.0, new ShapeMath.Rect(2.5, 4.0).area());
        check("Rect is a Shape", true, new ShapeMath.Rect(1.0, 1.0) instanceof Shape);

        check("totalArea of empty array", 0.0, ShapeMath.totalArea(new Shape[0]));

        Shape[] rectsOnly = { new ShapeMath.Rect(2.0, 2.0), new ShapeMath.Rect(1.0, 5.0) };
        check("totalArea of two rects", 9.0, ShapeMath.totalArea(rectsOnly));

        Shape[] mixed = { new Circle(1.0), new ShapeMath.Rect(2.0, 2.0) };
        check("totalArea circle r=1 + rect 2x2 (rounded to 2 decimals)", 7.14, round2(ShapeMath.totalArea(mixed)));

